from decimal import Decimal, InvalidOperation


class BusinessRuleViolation(Exception):
    """Legacy blocking validation failure."""

    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(message)


def _numeric_value(value: object) -> Decimal:
    """Apply legacy empty-string numeric coercion."""
    if value is None or value == "":
        return Decimal("0")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal("0")


def release_credit_hold(account: dict) -> tuple[dict, list[dict]]:
    """Release an account credit hold using legacy ACC-004 semantics."""
    updated_account = dict(account)

    if account.get("CRED_HOLD", "") != "Y":
        return updated_account, []

    if _numeric_value(account.get("CRED_LIMIT", "")) <= Decimal("0"):
        raise BusinessRuleViolation(
            code="E1004",
            message="Cannot release credit hold with zero credit limit",
        )

    updated_account["CRED_HOLD"] = "N"
    return updated_account, [
        {
            "code": "CRED_HOLD_OFF",
            "entity_id": str(account.get("ACCT_ID", "")),
        }
    ]
